#!/usr/bin/env python3
"""Regenerate numerical tables and vector-first diagnostic figures from curated scalars."""
import argparse,csv,json,os,sys
from pathlib import Path
import numpy as np
read=lambda p:json.loads(Path(p).read_text())
def table(headers,rows):return '| '+' | '.join(headers)+' |\n| '+' | '.join(['---']*len(headers))+' |\n'+''.join('| '+' | '.join(map(str,r))+' |\n' for r in rows)
def csv_out(p,rows):
 with p.open('w') as f:w=csv.DictWriter(f,fieldnames=list(rows[0]),lineterminator='\n');w.writeheader();w.writerows(rows)
def main(root,figures):
 ev=root/'evidence';s=read(ev/'STATIC_STATS.json');d=read(ev/'DYNAMIC_STATS.json');t=read(ev/'STATIC_TIMELINE.json')['aggregate'];m=read(ev/'METRICS.json')['metrics'];l2=read(ev/'L2_SUPPLEMENT.json') if (ev/'L2_SUPPLEMENT.json').exists() else None
 mode_names=['READ_ONLY','DISTANCE_ONLY','THRESHOLD_COUNT','FULL_OUTPUT'];mode_rows=[];last=None
 for k in mode_names:
  q=s['modes'][k]['query_ms'];mode_rows.append(dict(mode=k,median_ms=q['median'],p10_ms=q['p10'],p90_ms=q['p90'],signed_delta_previous_ms=None if last is None else q['median']-last));last=q['median']
 csv_out(ev/'ABLATION_TABLE.csv',mode_rows)
 scaling=[]
 for kind,cases in [('D',[(1000000,z,s['scaling']['D'+str(z)]) for z in (128,256,512)]+[(1000000,960,s['modes']['FULL_OUTPUT'])]),('N',[(z,960,s['scaling']['N'+str(z)]) for z in (100000,250000,500000)]+[(1000000,960,s['modes']['FULL_OUTPUT'])])]:
  for N,D,c in cases:
   q=c['query_ms'];scaling.append(dict(kind=kind,N=N,D=D,median_query_ms=q['median'],p10_ms=q['p10'],p90_ms=q['p90'],ns_per_object=q['median']*1e6/N,logical_bytes=N*D*4,logical_payload_GBs=N*D*4/q['median']/1e6,mean_hits=c['rows'][0]['mean_hits']))
 csv_out(ev/'SCALING_TABLE.csv',scaling)
 breakdown=[dict(component=k,diagnostic_mean_ms=v/32,share_percent=100*v/t['host_span_ms']) for k,v in t['components_ms'].items()]+[dict(component='exposed_Host_gap',diagnostic_mean_ms=t['exposed_Host_gap_ms']/32,share_percent=100*t['exposed_Host_gap_ms']/t['host_span_ms'])]
 csv_out(ev/'BREAKDOWN_TABLE.csv',breakdown)
 b=s['keeper']['keeper'];r=['# Exact scan diagnostic results\n\nGIST **N1M/D960 FP32 L2 B1**, original 32 range queries, radius bits 0x3f34a3d8. All primary values are the median of six process-level mean query intervals; p10/p90 are process quantiles, not per-query tails. Profilers are separate.\n']
 r+=['## 1. Unchanged native keeper\n',table(['Quantity','Median','p10','p90'],[['Query ACK (ms)',f"{b['query_ms']['median']:.6f}",f"{b['query_ms']['p10']:.6f}",f"{b['query_ms']['p90']:.6f}"],['Continuous 32-query pass (ms)',f"{b['pass_ms']['median']:.6f}",f"{b['pass_ms']['p10']:.6f}",f"{b['pass_ms']['p90']:.6f}"]]),'The later FULL_OUTPUT control has the same unmodified Scan::range body and bit-identical answer payloads, but additional persistent diagnostic workspace outside query timing. Keeper and later control processes are not genuinely paired. No speedup is claimed between them.\n']
 r+=['## 2. Controlled ablation\n',table(['Mode','Query median ms','p10','p90','Signed previous delta ms'],[[v['mode'],f"{v['median_ms']:.6f}",f"{v['p10_ms']:.6f}",f"{v['p90_ms']:.6f}",'—' if v['signed_delta_previous_ms'] is None else f"{v['signed_delta_previous_ms']:.6f}"] for v in mode_rows]),'These are different diagnostic pipelines, not additive exclusive phases or production replacements. READ_ONLY contains checksum/reduction; DISTANCE_ONLY contains score aggregation; THRESHOLD_COUNT substitutes a count reduction for full compaction. The tiny negative threshold-minus-distance delta is retained, not clipped.\n',table(['Paired numerator/denominator','Marginal median ratio','Paired geometric ratio','95% paired CI','Wins','Forward / reverse'],[[k,f"{v['marginal_median_ratio']:.6f}",f"{v['paired_geometric_ratio']:.6f}",f"[{v['paired_ratio_ci95'][0]:.6f}, {v['paired_ratio_ci95'][1]:.6f}]",v['process_wins'],f"{v['forward_geometric']:.6f} / {v['reverse_geometric']:.6f}"] for k,v in s['comparisons'].items()]),'Bootstrap: 20,000 paired process log-mean resamples, seed 2026101111. A win means numerator time < denominator; mode ratios are not system speedups.\n']
 r+=['## 3. Exclusive diagnostic timeline\n',table(['Component','Mean ms/query','Host-span share %'],[[v['component'],f"{v['diagnostic_mean_ms']:.6f}",f"{v['share_percent']:.4f}"] for v in breakdown]),f"GPU-active union={100*t['GPU_active_fraction']:.4f}% of one 32-query NVTX capture. Runtime APIs overlap it: cudaMemcpyAsync inclusive {t['API_inclusive_ms']['cudaMemcpyAsync_v3020']:.6f}ms, GPU overlap {t['API_GPU_overlap_ms']['cudaMemcpyAsync_v3020']:.6f}ms. Do not add API waits to GPU time. No allocation/free API occurs in this static measured span. Event phase spans remain diagnostic and may include Host enqueue/resize gaps.\n"]
 r+=['## 4. Main-kernel roofline\n',table(['Selected mode','NCU ms','DRAM read GB','DRAM write MB','L2 total GB','DRAM GB/s','FP32 executed TFLOP/s','Executed FLOP/DRAM byte','Occupancy %'],[[k,f"{v['duration_s']*1000:.6f}",f"{v['DRAM_read_bytes']/1e9:.6f}",f"{v['DRAM_write_bytes']/1e6:.6f}",f"{v['L2_bytes']/1e9:.6f}",f"{v['DRAM_GBs']:.3f}",f"{v['FP32_executed_TFLOPs']:.6f}",f"{v['executed_intensity']:.6f}",f"{v['occupancy_percent']:.4f}"] for k,v in m.items()]),'Each row is one first measured main-kernel launch, not all 32 queries, output kernels or the full Host interval. NCU replay uses 10 passes, no cache flush/clock modification. FP32 executed proxy = predicated-on FADD + FMUL +2*FFMA; FP64 add/mul/FMA counters are 0 here.\n',f"Useful model: 3.84GB and 2.879G scalar operations/query. The native kernel instead records 184.32G executed FP32 proxy FLOPs (~64.02x useful model); do not substitute useful FLOPs for executed work when explaining the roofline. Advertised peaks are 1597GB/s and 120TFLOP/s; the same-campaign reachable stream reference is {s['streaming_calibration']['reachable_reference_GBs']:.3f}GB/s, not a universal measured hardware maximum. D2D combined-read/write calibration is {s['streaming_calibration']['D2D_combined_read_write_event_GBs']:.3f}GB/s and READ_ONLY Host logical-payload rate is {s['streaming_calibration']['READ_ONLY_logical_payload_GBs']:.3f}GB/s. Counter GB/s always uses duration from the same NCU capture.\n"]
 if l2:r += [f"Supplemental L2 capture: read {l2['read_L2_bytes']:,}B, write {l2['write_L2_bytes']:,}B, Other {l2['other_L2_bytes']:,}B, total {l2['total_L2_bytes']:,}B. All are 32-byte request sectors. Other subtype is unknown. The initial two-bucket assertion was rejected offline; runtime and all 40 answers were already valid. This separate capture is not mixed with the earlier main-kernel L2 total, and no GPU rerun was used for the interpretation correction.\n"]
 r+=['## 5. N and D scaling\n',table(['Series','N','D','Query ms','ns/object','Logical payload GB/s','Mean hits'],[[v['kind'],v['N'],v['D'],f"{v['median_query_ms']:.6f}",f"{v['ns_per_object']:.6f}",f"{v['logical_payload_GBs']:.3f}",f"{v['mean_hits']:.5f}"] for v in scaling]),'The GB/s column is logical vector bytes divided by Host ACK, not measured DRAM throughput. Lower-D output selectivity is not matched: D128/256/512 means 1.1875/16.84375/103.875 versus 205.9375 at D960. D scaling is therefore descriptive, not a pure same-hit arithmetic/memory attribution. N prefixes keep original Host query vectors and radius even when qid is outside the prefix.\n','## 6. Selectivity\n',table(['Radius label','Actual mean hits','Query ms'],[['low',s['scaling']['R_low']['rows'][0]['mean_hits'],f"{s['scaling']['R_low']['query_ms']['median']:.6f}"],['mid',205.9375,f"{s['modes']['FULL_OUTPUT']['query_ms']['median']:.6f}"],['high',s['scaling']['R_high']['rows'][0]['mean_hits'],f"{s['scaling']['R_high']['query_ms']['median']:.6f}"]]),'The target 10/current/10x-current counts are not attained; no post-measurement retuning. Actual high/low hit count grows 8.210x but the paired time ratio CI crosses 1. This rejects a large output bottleneck only within this attained sparse-output range, not dense answers or all query distributions.\n']
 r+=['## 7. Fixed 336-event dynamic workflow\n',f"Continuous trace median {d['continuous_trace_ms']['median']:.6f}ms includes service release but excludes setup/context/warmup/disk. Sum of operation ACKs is a distinct denominator.\n",table(['Operation','Count','Median total ACK ms','Median event p50 ms','Median event p95 ms'],[[k,40 if k in ('insert','delete') else 128,f"{v['sum_ms']['median']:.6f}",f"{v['p50']['median']:.6f}",f"{v['p95']['median']:.6f}"] for k,v in d['operations'].items()]),f"Median update ACK share of continuous trace={100*d['update_fraction_of_continuous']['median']:.6f}%; UPDATE_BOUND fails. Inserts move 153,600 H2D bytes ; 20 swap deletions move 76,880 D2D bytes; no rebuild. Historical 0.532743/0.293380ms entries were 40-operation ACK sums, not per-operation medians. CPU rusage/trace ratio={d['CPU_core_equivalent']['median']:.6f} core-equivalent. It does not identify CPU arithmetic or driver polling without sampled stacks.\n"]
 dt=read(ev/'DYNAMIC_TIMELINE.json')['aggregate'];r+=[f"One dynamic NSYS capture has GPU-active fraction {100*dt['GPU_active_fraction']:.4f}%. It includes one lazy cudaHostAlloc call ({dt['API_inclusive_ms']['cudaHostAlloc_v3020']:.6f}ms), charged to the first measured kNN after cloned warmup restoration. This is not an update cost, and moving it to setup would not remove cold-service work. Secondary kNN uses native Faiss with use_cuvs=false; do not transfer the range-kernel resource classification to kNN.\n"]
 if (ev/'MATCHED.json').exists():
  q=read(ev/'MATCHED.json');vals=[float(r['host_ms']) for r in q['rows'][8:]];r += ['## 8. Ordered-FP64 reference\n',f"One diagnostic process: all 40 complete answers and field bits pass; measured 32 query mean {np.mean(vals):.6f}ms. This is not a six-process native comparator, paired ratio or system speedup. Tree/packed setup outside this reference interval is retained in metadata; no tree query is executed.\n"]
 (root/'RESULTS.md').write_text('\n'.join(r))
 if not figures:return
 sys.path.insert(0,str(Path(os.environ.get('AGENTS_SKILLS_HOME',Path.home()/'.agents/skills'))/'paper-figures/scripts'));from paper_style import setup_style,save_fig,roofline,add_panel_labels
 import matplotlib.pyplot as plt
 setup_style('acm_double',use_latex=False);figdir=root/'figures';figdir.mkdir(exist_ok=True)
 def save(fig,name,width):save_fig(fig,name,formats=('pdf','svg','png'),output_dir=figdir,target_width_inches=width);plt.close(fig);svg=figdir/(name+'.svg');svg.write_text('\n'.join(line.rstrip() for line in svg.read_text().splitlines())+'\n')
 labels=['Read\nonly','Distance\nonly','Threshold\ncount','Full\noutput'];fig,ax=plt.subplots(figsize=(3.5,2.8),layout='constrained');x=np.arange(4);med=[r['median_ms'] for r in mode_rows];lo=[r['median_ms']-r['p10_ms'] for r in mode_rows];hi=[r['p90_ms']-r['median_ms'] for r in mode_rows];ax.bar(x,med,color=['#999999','#0072B2','#0072B2','#0072B2'],edgecolor='black',linewidth=.6,yerr=np.array([lo,hi]),capsize=3)
 for i,k in enumerate(mode_names):ax.scatter(i+np.linspace(-.065,.065,6),s['modes'][k]['query_ms']['process_values'],s=12,facecolor='white',edgecolor='black',zorder=3);ax.text(i,max(s['modes'][k]['query_ms']['p90'],med[i])+.14,f'{med[i]:.3f}',ha='center',fontsize=8)
 ax.set_xticks(x,labels);ax.set_ylabel('Query ACK (ms)');ax.set_ylim(0,3.9);save(fig,'controlled_ablation',3.5)
 fig,axes=plt.subplots(1,2,figsize=(7,2.8),layout='constrained')
 for ax,kind in zip(axes,('D','N')):
  rr=[r for r in scaling if r['kind']==kind];xx=np.array([r['D'] if kind=='D' else r['N']/1000 for r in rr]);yy=np.array([r['median_query_ms'] for r in rr]);err=np.array([[r['median_query_ms']-r['p10_ms'] for r in rr],[r['p90_ms']-r['median_query_ms'] for r in rr]])
  ax.errorbar(xx,yy,yerr=err,fmt='o-',color='#0072B2',capsize=3);ax.plot(xx,xx/xx[-1]*yy[-1],'--',color='#777777',lw=.8,label='Proportional anchor');ax.set_xticks(xx);ax.set_ylim(0,3.8);ax.set_xlabel('Dimensions' if kind=='D' else 'Vectors (thousands)');ax.set_ylabel('Query ACK (ms)');ax.legend(loc='upper left',fontsize=7)
 add_panel_labels(axes);save(fig,'N_D_scaling',7)
 fig,ax=plt.subplots(figsize=(3.5,2.8),layout='constrained');qq=[s['scaling']['R_low']['query_ms'],s['modes']['FULL_OUTPUT']['query_ms'],s['scaling']['R_high']['query_ms']];v=np.array([q['median'] for q in qq]);err=np.array([[q['median']-q['p10'] for q in qq],[q['p90']-q['median'] for q in qq]]);ax.bar(range(3),v,color='#0072B2',edgecolor='black',lw=.6,yerr=err,capsize=3);ax.set_xticks(range(3),['Low\n200 hits','Mid\n206 hits','High\n1645 hits']);ax.set_ylim(0,3.9);ax.set_ylabel('Query ACK (ms)');save(fig,'attained_selectivity',3.5)
 points=[('Read only',m['read']['executed_intensity'],m['read']['FP32_executed_TFLOPs'],'#777777'),('Distance only',m['distance']['executed_intensity'],m['distance']['FP32_executed_TFLOPs'],'#0072B2'),('Full: distance kernel',m['full']['executed_intensity'],m['full']['FP32_executed_TFLOPs'],'black')];fig,ax=roofline(120,1.597,points,xlabel='Executed intensity (FLOP/DRAM byte)',ylabel='Executed FP32 proxy (TFLOP/s)');fig.set_size_inches(3.5,3.0);fig.set_layout_engine('constrained');I=np.logspace(-1,2.3,100);ax.plot(I,np.minimum(120,I*s['streaming_calibration']['reachable_reference_GBs']/1000),'--',color='#777777',lw=.8,label='Stream reference');ax.set_xlim(.1,200);ax.set_ylim(.1,180);ax.texts[0].set_visible(False);ax.text(.48,.28,'Read only',fontsize=7);ax.texts[1].set_visible(False);ax.texts[2].set_visible(False);ax.annotate('Native distance\n(both captures)',(m['full']['executed_intensity'],m['full']['FP32_executed_TFLOPs']),xytext=(.75,35),textcoords='data',ha='left',va='top',fontsize=7,arrowprops=dict(arrowstyle='-',lw=.6,color='black'));ax.lines[0].set_label('Advertised peak');ax.legend(fontsize=7,loc='lower right');save(fig,'executed_roofline',3.5)
 fig,axes=plt.subplots(1,2,figsize=(7,2.8),layout='constrained');fused=t['components_ms']['distance_fused_read_arithmetic']/32;other=(t['GPU_active_ms']-t['components_ms']['distance_fused_read_arithmetic'])/32;host=t['exposed_Host_gap_ms']/32;left=0
 for name,value,color in [('Fused scan',fused,'#0072B2'),('Other GPU',other,'#999999'),('Host gap',host,'black')]:axes[0].barh([0],[value],left=[left],height=.5,color=color,label=name);left+=value
 axes[0].text(fused/2,0,'Fused scan: 97.19%',ha='center',va='center',color='white',fontsize=8);axes[0].set_yticks([0],['Full\noutput']);axes[0].set_xlim(0,3.7);axes[0].set_xlabel('Diagnostic Host span (ms/query)');axes[0].legend(fontsize=7,loc='upper center',bbox_to_anchor=(.5,-.2),ncol=2)
 non=[r for r in breakdown if r['component']!='distance_fused_read_arithmetic'];names=['H2D','Predicate','Compaction','Fields/observer','D2H','Host gap'];assert len(non)==6;vv=[next(r['diagnostic_mean_ms']*1000 for r in non if r['component']==key) for key in ('copy_Host-to-Device','predicate','compaction','output_fields_and_observer','copy_Device-to-Host','exposed_Host_gap')];axes[1].barh(range(6),vv,color=['#777777']*5+['black']);axes[1].set_yticks(range(6),names);axes[1].set_xlabel('Non-scan diagnostic time (µs/query)');axes[1].set_xlim(0,90);add_panel_labels(axes);save(fig,'exclusive_timeline',7)
 (figdir/'CAPTIONS.md').write_text('''# Diagnostic figure captions\n\n- **controlled_ablation:** The coordinate-read control costs 75.9% of full query ACK, whereas count-to-full contrast is only 0.75%. Bars are medians of six process mean queries; whiskers p10/p90; all six observations retained. Partial controls are not production replacements or additive cost buckets.\n- **executed_roofline:** Native B1 distance executes a much larger arithmetic proxy than useful L2 work, yet remains on the memory branch and below the reachable streaming rate. Each point uses executed predicated-on counters and duration from the same independent NCU main-kernel capture, not Host latency. Full denotes its distance component only; useful model 2.879G versus executed 184.32G is not 64x potential speedup. Peaks are advertised theoretical bounds.\n- **N_D_scaling:** Scan latency scales with deterministic vector work, with fixed-cost overhead. Points are process medians, whiskers p10/p90, six processes per case. D output counts are not matched; N1M/D960 anchor is the independent primary stage, not a paired scaling repetition. Dashed curves are proportional anchors, not fitted performance models.\n- **attained_selectivity:** Actual sparse-output hit count increases 8.21x between low/high with no confirmed large query penalty. Bars median and p10/p90 of six processes. Intended 10/206/2059 targets are not attained; actual 200/206/1645 shown, and no inference to dense output.\n- **exclusive_timeline:** GPU-active work occupies 97.7% of a complete-query diagnostic span; exposed Host gap and complete-output GPU phases are small. One independent NSYS process, 32 measured queries, averages of clipped GPU interval unions; no public latency denominator or independent-process confidence interval. Input read and arithmetic are fused and not fabricated as exclusive bars.\n''')
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--artifact',type=Path,required=True);p.add_argument('--figures',action='store_true');a=p.parse_args();main(a.artifact,a.figures)
